def add(a, b):
    return a + b

def shout(text):
    return text.upper() + "!"

TOOLS = {"add": add, "shout": shout}

def dispatch(call, tools):
    """Look up call['name'] in tools and call it with call['args']."""
    fn = tools.get(call["name"])
    if fn is None:
        return f"error: unknown tool {call['name']}"
    return fn(**call["args"])

print(dispatch({"name": "add", "args": {"a": 4, "b": 5}}, TOOLS))
print(dispatch({"name": "shout", "args": {"text": "tools"}}, TOOLS))
print(dispatch({"name": "delete_file", "args": {"path": "x"}}, TOOLS))
